def test_v_12():
    try:
        import ast
        tree = ast.parse(_read("main/tests.py"))
        funcs = [n for n in ast.walk(tree) if isinstance(n, (ast.FunctionDef, ast.AsyncFunctionDef))]
        patchers = []
        for fn in funcs:
            args = {a.arg for a in fn.args.args}
            uses_setattr = any(isinstance(n, ast.Call) and isinstance(n.func, ast.Attribute) and n.func.attr == "setattr" for n in ast.walk(fn))
            if "monkeypatch" in args and uses_setattr:
                patchers.append(fn)
        assert patchers
        fixture_names = {fn.name for fn in patchers if any((isinstance(d, ast.Name) and d.id == "fixture") or (isinstance(d, ast.Attribute) and d.attr == "fixture") for d in fn.decorator_list)}
        tests = [fn for fn in funcs if fn.name.startswith("test_")]
        isolated = [fn for fn in tests if ({a.arg for a in fn.args.args} & ({"monkeypatch"} | fixture_names))]
        assert len(isolated) >= 4
        _mark_outcome('test_v_12', "passed")
    except AssayVerifierBroken as _avb:
        _mark_outcome('test_v_12', "broken")
        raise AssertionError("ASSAY_BROKEN " + str(_avb))
    except AssertionError as _ae:
        _mark_outcome('test_v_12', "absent" if 'missing file:' in str(_ae) else "failed")
        raise
    except BaseException as _e:
        _mark_outcome('test_v_12', "broken")
        raise

